    "id": "revisao-ccp-ccp-completo-366-dez",
    "law": "ccp",
    "topic": "Contratação pública: conceitos, procedimentos e casos de RH",
    "subtopic": "Suspensão pelo empreiteiro",
    "familyId": "ccp:revisao-ccp-completo-366-dez",
    "conceptId": "ccp:revisao-ccp-completo-366-dez",
