    "article": "Ponto III.2",
    "articleNumber": "III.2",
    "questionType": "caso-pratico-ap",
    "officialSource": "https://www.madeira.gov.pt/drot/pesquisar/ctl/ReadInformcao/mid/1894/InformacaoId/254482/UnidadeOrganicaId/12/LiveSearch/OR%C3%87/2026",
